  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
  5→  Delete,
  6→  Body,
  7→  HttpCode,
  8→  HttpStatus,
  9→  UseGuards,
 10→  Request,
 11→  Res,
 12→  Req,
 13→  UnauthorizedException,
 14→  BadRequestException,
 15→} from '@nestjs/common';
 16→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
 17→import { Response, Request as ExpressRequest } from 'express';
 18→import { AuthService } from './auth.service';
 19→import { LoginDto, LoginResponseDto } from './dto/login.dto';
 20→import { TokenResponseDto, DesktopRefreshDto, LogoutResponseDto } from './dto/token.dto';
 21→import { TestLoginDto, TestLoginResponseDto } from './dto/test-login.dto';
 22→import {
 23→  LinkMethodDto,
 24→  AuthMethodResponseDto,
 25→  UnlinkMethodDto,
 26→  UnlinkMethodResponseDto,
 27→} from './dto/link-method.dto';
 28→import { DeleteAccountDto, DeleteAccountResponseDto } from './dto/delete-account.dto';
 29→import { ThrottlerGuard } from '@nestjs/throttler';
 30→import { Throttle } from '@nestjs/throttler';
 31→import { JwtAuthGuard } from './guards/jwt-auth.guard';
 32→import { User } from './entities/user.entity';
 33→import { MetricsService } from '../metrics/metrics.service';
 34→
 35→interface RequestWithUser extends Request {
 36→  user: User;
 37→}
 38→
 39→// Cookie configuration
 40→const REFRESH_TOKEN_COOKIE_OPTIONS = {
 41→  httpOnly: true,
 42→  secure: process.env.NODE_ENV === 'production',
 43→  sameSite: 'lax' as const,
 44→  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
 45→  path: '/auth', // Only sent to auth endpoints
 46→};
 47→
 48→@ApiTags('Auth')
 49→@Controller('auth')
 50→export class AuthController {
 51→  constructor(
 52→    private authService: AuthService,
 53→    private readonly metricsService: MetricsService
 54→  ) {}
 55→
 56→  @Post('login')
 57→  @HttpCode(HttpStatus.OK)
 58→  @UseGuards(ThrottlerGuard)
 59→  @Throttle({ default: { limit: 10, ttl: 60000 } })
 60→  @ApiOperation({ summary: 'Authenticate user with Web3Auth ID token' })
 61→  @ApiResponse({
 62→    status: 200,
 63→    description: 'Successfully authenticated',
 64→    type: LoginResponseDto,
 65→  })
 66→  @ApiResponse({ status: 401, description: 'Invalid Web3Auth token' })
 67→  async login(
 68→    @Body() loginDto: LoginDto,
 69→    @Req() req: ExpressRequest,
 70→    @Res({ passthrough: true }) res: Response
 71→  ): Promise<LoginResponseDto> {
 72→    const result = await this.authService.login(loginDto);
 73→    this.metricsService.authLogins.inc({
 74→      method: 'web3auth',
 75→      new_user: String(result.isNewUser),
 76→    });
 77→    const isDesktop = req.headers['x-client-type'] === 'desktop';
 78→
 79→    if (isDesktop) {
 80→      // Desktop clients: return refreshToken in response body (no cookie)
 81→      return {
 82→        accessToken: result.accessToken,
 83→        refreshToken: result.refreshToken,
 84→        isNewUser: result.isNewUser,
 85→      };
 86→    }
 87→
 88→    // Web clients: set refresh token in HTTP-only cookie
 89→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
 90→
 91→    return {
 92→      accessToken: result.accessToken,
 93→      isNewUser: result.isNewUser,
 94→    };
 95→  }
 96→
 97→  @Post('refresh')
 98→  @HttpCode(HttpStatus.OK)
 99→  @ApiOperation({ summary: 'Refresh access token using HTTP-only refresh token cookie' })
100→  @ApiResponse({
101→    status: 200,
102→    description: 'Tokens refreshed successfully',
103→    type: TokenResponseDto,
104→  })
105→  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
106→  async refresh(
107→    @Req() req: ExpressRequest,
108→    @Body() body: DesktopRefreshDto,
109→    @Res({ passthrough: true }) res: Response
110→  ): Promise<TokenResponseDto> {
111→    const isDesktop = req.headers['x-client-type'] === 'desktop';
112→
113→    let refreshToken: string | undefined;
114→
115→    if (isDesktop) {
116→      // Desktop clients: read refresh token from request body
117→      refreshToken = body?.refreshToken;
118→    } else {
119→      // Web clients: read refresh token from cookie
120→      refreshToken = req.cookies?.['refresh_token'];
121→    }
122→
123→    if (!refreshToken) {
124→      throw new UnauthorizedException('No refresh token');
125→    }
126→
127→    const result = await this.authService.refreshByToken(refreshToken);
128→
129→    if (isDesktop) {
130→      // Desktop clients: return new refreshToken in response body (no cookie)
131→      return {
132→        accessToken: result.accessToken,
133→        refreshToken: result.refreshToken,
134→        email: result.email,
135→      };
136→    }
137→
138→    // Web clients: set new refresh token in HTTP-only cookie (rotation)
139→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
140→
141→    return {
142→      accessToken: result.accessToken,
143→      email: result.email,
144→    };
145→  }
146→
147→  @Post('logout')
148→  @HttpCode(HttpStatus.OK)
149→  @UseGuards(JwtAuthGuard)
150→  @ApiBearerAuth()
151→  @ApiOperation({ summary: 'Logout user and invalidate all refresh tokens' })
152→  @ApiResponse({
153→    status: 200,
154→    description: 'Successfully logged out',
155→    type: LogoutResponseDto,
156→  })
157→  @ApiResponse({ status: 401, description: 'Unauthorized' })
158→  async logout(
159→    @Request() req: RequestWithUser,
160→    @Res({ passthrough: true }) res: Response
161→  ): Promise<LogoutResponseDto> {
162→    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';
163→
164→    if (!isDesktop) {
165→      // Web clients: clear the refresh token cookie
166→      res.clearCookie('refresh_token', { path: '/auth' });
167→    }
168→
169→    return this.authService.logout(req.user.id);
170→  }
171→
172→  @Delete('account')
173→  @HttpCode(HttpStatus.OK)
174→  @UseGuards(ThrottlerGuard)
175→  @Throttle({ default: { limit: 3, ttl: 60000 } })
176→  @UseGuards(JwtAuthGuard)
177→  @ApiBearerAuth()
178→  @ApiOperation({ summary: 'Permanently delete user account and all associated data' })
179→  @ApiResponse({
180→    status: 200,
181→    description: 'Account deleted successfully',
182→    type: DeleteAccountResponseDto,
183→  })
184→  @ApiResponse({ status: 400, description: 'Invalid confirmation or account not found' })
185→  @ApiResponse({ status: 401, description: 'Unauthorized' })
186→  async deleteAccount(
187→    @Request() req: RequestWithUser,
188→    @Body() dto: DeleteAccountDto,
189→    @Res({ passthrough: true }) res: Response
190→  ): Promise<DeleteAccountResponseDto> {
191→    if (dto.confirmation !== 'DELETE') {
192→      throw new BadRequestException('Confirmation must be the string "DELETE"');
193→    }
194→    const result = await this.authService.deleteAccount(req.user.id);
195→    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';
196→    if (!isDesktop) {
197→      res.clearCookie('refresh_token', { path: '/auth' });
198→    }
199→    return result;
200→  }
201→
202→  @Get('methods')
203→  @UseGuards(JwtAuthGuard)
204→  @ApiBearerAuth()
205→  @ApiOperation({ summary: 'Get all linked auth methods for the current user' })
206→  @ApiResponse({
207→    status: 200,
208→    description: 'List of linked auth methods',
209→    type: [AuthMethodResponseDto],
210→  })
211→  @ApiResponse({ status: 401, description: 'Unauthorized' })
212→  async getMethods(@Request() req: RequestWithUser): Promise<AuthMethodResponseDto[]> {
213→    return this.authService.getLinkedMethods(req.user.id);
214→  }
215→
216→  @Post('link')
217→  @HttpCode(HttpStatus.OK)
218→  @UseGuards(JwtAuthGuard)
219→  @ApiBearerAuth()
220→  @ApiOperation({ summary: 'Link a new auth method to the current user account' })
221→  @ApiResponse({
222→    status: 200,
223→    description: 'Auth method linked successfully, returns updated list of methods',
224→    type: [AuthMethodResponseDto],
225→  })
226→  @ApiResponse({ status: 400, description: 'Auth method already linked or publicKey mismatch' })
227→  @ApiResponse({ status: 401, description: 'Unauthorized' })
228→  async linkMethod(
229→    @Request() req: RequestWithUser,
230→    @Body() linkDto: LinkMethodDto
231→  ): Promise<AuthMethodResponseDto[]> {
232→    return this.authService.linkMethod(req.user.id, linkDto);
233→  }
234→
235→  @Post('unlink')
236→  @HttpCode(HttpStatus.OK)
237→  @UseGuards(JwtAuthGuard)
238→  @ApiBearerAuth()
239→  @ApiOperation({ summary: 'Unlink an auth method from the current user account' })
240→  @ApiResponse({
241→    status: 200,
242→    description: 'Auth method unlinked successfully',
243→    type: UnlinkMethodResponseDto,
244→  })
245→  @ApiResponse({ status: 400, description: 'Cannot unlink last auth method or method not found' })
246→  @ApiResponse({ status: 401, description: 'Unauthorized' })
247→  async unlinkMethod(
248→    @Request() req: RequestWithUser,
249→    @Body() unlinkDto: UnlinkMethodDto
250→  ): Promise<UnlinkMethodResponseDto> {
251→    await this.authService.unlinkMethod(req.user.id, unlinkDto.methodId);
252→    return { success: true };
253→  }
254→
255→  @Post('test-login')
256→  @HttpCode(HttpStatus.OK)
257→  @UseGuards(ThrottlerGuard)
258→  @Throttle({ default: { limit: 5, ttl: 900000 } })
259→  @ApiOperation({
260→    summary: 'Test-only login bypassing Core Kit (requires TEST_LOGIN_SECRET)',
261→  })
262→  @ApiResponse({
263→    status: 200,
264→    description: 'Test login successful',
265→    type: TestLoginResponseDto,
266→  })
267→  @ApiResponse({ status: 403, description: 'Test login not enabled' })
268→  @ApiResponse({ status: 401, description: 'Invalid secret' })
269→  async testLogin(
270→    @Body() dto: TestLoginDto,
271→    @Res({ passthrough: true }) res: Response
272→  ): Promise<TestLoginResponseDto> {
