 63→  async login(loginDto: LoginDto): Promise<LoginServiceResult> {
 64→    // 1. Verify CipherBox-issued JWT.
 65→    // All auth methods now go through: CipherBox identity provider -> Core Kit loginWithJWT -> /auth/login.
 66→    const payload = await this.verifyCipherBoxJwt(loginDto.idToken);
 67→
 68→    // 2. Find or create user
 69→    let user = await this.userRepository.findOne({
 70→      where: { publicKey: loginDto.publicKey },
 71→    });
 72→
 73→    // 2b. Placeholder publicKey resolution for Core Kit identity provider.
 74→    // When a user first authenticates via CipherBox identity provider,
 75→    // they get a placeholder publicKey ('pending-core-kit-{userId}').
 76→    // After Core Kit login, the client calls /auth/login with the REAL publicKey.
 77→    // We need to find the placeholder user and update their publicKey.
 78→    if (!user) {
 79→      const verifierId = payload.verifierId || payload.sub;
 80→      if (verifierId) {
 81→        const placeholderUser = await this.userRepository.findOne({
 82→          where: { publicKey: Like(`pending-core-kit-${verifierId}%`) },
 83→        });
 84→        if (placeholderUser) {
 85→          this.logger.log(`Resolving placeholder publicKey for user ${placeholderUser.id}`);
 86→          placeholderUser.publicKey = loginDto.publicKey;
 87→          user = await this.userRepository.save(placeholderUser);
 88→        }
 89→      }
 90→    }
 91→
 92→    const isNewUser = !user;
 93→    if (!user) {
 94→      user = await this.userRepository.save({
 95→        publicKey: loginDto.publicKey,
 96→      });
 97→    }
 98→
 99→    // 3. Find or create auth method
100→    // The identity controller already created the auth method
101→    // (with the correct type: 'google', 'email', or 'wallet'). Look up by
102→    // userId + identifierHash to avoid creating duplicates with a hardcoded type.
103→    let authMethod: AuthMethod | null;
104→
105→    const identifier = payload.email || payload.sub;
106→    if (!identifier) {
107→      this.logger.warn('CipherBox JWT missing both email and sub claims');
108→      throw new UnauthorizedException('Invalid identity token: missing identifier');
109→    }
110→    const identifierHash = this.siweService.hashIdentifier(identifier);
111→    authMethod = await this.authMethodRepository.findOne({
112→      where: { userId: user.id, identifierHash },
113→    });
114→    if (!authMethod) {
115→      // Fallback: find any auth method for this user (identity controller should have created one)
116→      authMethod = await this.authMethodRepository.findOne({
117→        where: { userId: user.id },
118→      });
119→    }
120→    if (!authMethod) {
121→      // Safety net: create auth method if identity controller didn't (shouldn't happen in practice)
122→      // All logins go through loginType='corekit' now, but infer type from identifier format
123→      const inferredType = identifier.startsWith('0x') ? 'wallet' : 'email';
124→      const display =
125→        inferredType === 'wallet'
126→          ? this.siweService.truncateWalletAddress(identifier)
127→          : this.siweService.truncateEmail(identifier);
128→      authMethod = await this.authMethodRepository.save({
129→        userId: user.id,
130→        type: inferredType,
131→        identifier: identifierHash,
132→        identifierHash,
133→        identifierDisplay: display,
134→      });
135→    }
136→
137→    // 4. Update last used timestamp
138→    authMethod.lastUsedAt = new Date();
139→    await this.authMethodRepository.save(authMethod);
140→
141→    // 5. Create tokens
142→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
143→
144→    return {
145→      accessToken: tokens.accessToken,
146→      refreshToken: tokens.refreshToken,
147→      isNewUser,
148→    };
149→  }
