151→  /**
152→   * Verify a CipherBox-issued JWT for Core Kit login flow.
153→   * Since we are the identity provider, we verify against our own JWKS.
154→   */
155→  private async verifyCipherBoxJwt(
156→    idToken: string
157→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
158→    try {
159→      const jwksData = this.jwtIssuerService.getJwksData();
160→      const jwks = jose.createLocalJWKSet(jwksData);
161→      const { payload } = await jose.jwtVerify(idToken, jwks, {
162→        issuer: 'cipherbox',
163→        audience: 'web3auth',
164→        algorithms: ['RS256'],
165→      });
166→      return {
167→        sub: payload.sub,
168→        verifierId: payload.sub,
169→        email: payload.email as string | undefined,
170→      };
171→    } catch (error) {
172→      this.logger.warn(
173→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
174→      );
175→      throw new UnauthorizedException('Invalid CipherBox identity token');
176→    }
177→  }
