197→  /**
198→   * Permanently delete a user account and all associated data.
199→   *
200→   * 1. Unpins all IPFS content from the local Kubo node (best-effort)

200→   * 1. Unpins all IPFS content from the local Kubo node (best-effort)
201→   * 2. Deletes the user row — ON DELETE CASCADE handles cleanup of
202→   *    auth_methods, refresh_tokens, vaults, pinned_cids, folder_ipns,
203→   *    ipns_republish_schedule, shares, share_keys, and share_invites.
204→   */
205→  async deleteAccount(userId: string): Promise<{ success: boolean }> {
206→    // Fetch all pinned CIDs before cascade deletes the records
207→    const pinnedCids = await this.pinnedCidRepository.find({
208→      where: { userId },
209→      select: ['cid'],
210→    });
211→
212→    // Unpin all content from Kubo (best-effort, don't block deletion on failure)
213→    if (pinnedCids.length > 0) {
214→      const results = await Promise.allSettled(
215→        pinnedCids.map((pin) => this.ipfsProvider.unpinFile(pin.cid))
216→      );
217→      const failed = results.filter((r) => r.status === 'rejected').length;
218→      this.logger.log(
219→        `Unpinned ${pinnedCids.length - failed}/${pinnedCids.length} CIDs for user ${userId}` +
220→          (failed > 0 ? ` (${failed} failed)` : '')
221→      );
222→    }
223→
224→    // Delete user row — cascade handles all related DB records
225→    const result = await this.userRepository.delete(userId);
226→    if (result.affected === 0) {
227→      throw new BadRequestException('Account not found');
228→    }
229→    this.logger.log(`Account deleted: userId=${userId}`);
230→    return { success: true };
231→  }
