233→  /**
234→   * Refresh tokens by searching for the matching refresh token across all users.
235→   * This allows refresh without requiring the (possibly expired) access token.
236→   */
237→  async refreshByToken(refreshToken: string): Promise<RefreshServiceResult> {
238→    // Find candidate tokens by prefix for O(1) lookup instead of O(N) Argon2 scan
239→    const prefix = refreshToken.substring(0, 16);
240→    const tokens = await this.refreshTokenRepository.find({
241→      where: {
242→        tokenPrefix: prefix,
243→        revokedAt: IsNull(),
244→      },
245→      relations: ['user'],
246→    });
247→
248→    // Find matching token by verifying against hashes
249→    let validToken: RefreshToken | null = null;
250→    for (const token of tokens) {
251→      // Skip expired tokens
252→      if (token.expiresAt < new Date()) {
253→        continue;
254→      }
255→      try {
256→        if (await argon2.verify(token.tokenHash, refreshToken)) {
257→          validToken = token;
258→          break;
259→        }
260→      } catch {
261→        // argon2.verify throws on invalid hash format, continue checking
262→        continue;
263→      }
264→    }
265→
266→    if (!validToken) {
267→      throw new UnauthorizedException('Invalid or expired refresh token');
268→    }
269→
270→    // Revoke old token
271→    validToken.revokedAt = new Date();
272→    await this.refreshTokenRepository.save(validToken);
273→
274→    // Create new tokens
275→    const newTokens = await this.tokenService.createTokens(
276→      validToken.userId,
277→      validToken.user.publicKey
278→    );
279→
280→    // Look up user's email from their most recently used auth method
281→    // (covers both email and google auth methods)
282→    const emailMethod = await this.authMethodRepository.findOne({
283→      where: [
284→        { userId: validToken.userId, type: 'email' },
285→        { userId: validToken.userId, type: 'google' },
286→      ],
287→      order: { lastUsedAt: 'DESC' },
288→    });
289→
290→    return {
291→      accessToken: newTokens.accessToken,
292→      refreshToken: newTokens.refreshToken,
293→      // H-09: Fall back to undefined instead of leaking raw identifier hash
294→      email: emailMethod?.identifierDisplay || undefined,
295→    };
296→  }
