298→  /**
299→   * Get all linked auth methods for a user.
300→   * Returns identifierDisplay (human-readable) for all method types.
301→   * Falls back to identifier if identifierDisplay is not set.
302→   */
303→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
304→    const methods = await this.authMethodRepository.find({
305→      where: { userId },
306→      order: { createdAt: 'ASC' },
307→    });
308→
309→    return methods.map((method) => ({
310→      id: method.id,
311→      type: method.type,
312→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
313→      identifier: method.identifierDisplay || '[redacted]',
314→      lastUsedAt: method.lastUsedAt,
315→      createdAt: method.createdAt,
316→    }));
317→  }
