319→  /**
320→   * Link a new auth method to an existing user account.
321→   *
322→   * For Google/email: verifies CipherBox-issued JWT to confirm ownership of the new method.
323→   * For wallet: verifies SIWE message+signature to confirm wallet ownership.
324→   *
325→   * Cross-account collision: if the auth method already belongs to a different user,
326→   * a BadRequestException is thrown (user must unlink from the other account first).
327→   */
328→  async linkMethod(userId: string, linkDto: LinkMethodDto): Promise<AuthMethodResponseDto[]> {
329→    // 1. Get the user
330→    const user = await this.userRepository.findOne({ where: { id: userId } });
331→    if (!user) {
332→      throw new UnauthorizedException('User not found');
333→    }
334→
335→    const authMethodType = linkDto.loginType;
336→
337→    if (authMethodType === 'wallet') {
338→      // Wallet linking: verify SIWE message + signature
339→      return this.linkWalletMethod(userId, linkDto);
340→    }
341→
342→    // Google/email linking: verify CipherBox-issued JWT
343→    return this.linkJwtMethod(userId, linkDto);
344→  }
