346→  /**
347→   * Link a Google or email auth method via CipherBox JWT verification.
348→   */
349→  private async linkJwtMethod(
350→    userId: string,
351→    linkDto: LinkMethodDto
352→  ): Promise<AuthMethodResponseDto[]> {
353→    // 1. Verify the CipherBox-issued JWT
354→    const payload = await this.verifyCipherBoxJwt(linkDto.idToken);
355→
356→    // 2. Determine type and identifier, hash for lookup
357→    const authMethodType = linkDto.loginType;
358→    const identifier = payload.email || payload.sub;
359→    if (!identifier) {
360→      throw new BadRequestException('Cannot determine identifier from JWT');
361→    }
362→    const identifierHash = this.siweService.hashIdentifier(identifier);
363→
364→    // 3. Check cross-account collision: same identifier linked to a different user
365→    const crossAccountMethod = await this.authMethodRepository.findOne({
366→      where: {
367→        type: authMethodType,
368→        identifierHash,
369→        userId: Not(userId),
370→      },
371→    });
372→
373→    if (crossAccountMethod) {
374→      throw new BadRequestException(
375→        `This ${authMethodType === 'google' ? 'Google account' : 'email'} is already linked to another account`
376→      );
377→    }
378→
379→    // 4. Check if this exact method is already linked to this user
380→    const existingMethod = await this.authMethodRepository.findOne({
381→      where: {
382→        userId,
383→        type: authMethodType,
384→        identifierHash,
385→      },
386→    });
387→
388→    if (existingMethod) {
389→      throw new BadRequestException('This auth method is already linked to your account');
390→    }
391→
392→    // 5. Create new AuthMethod entity with hashed identifier
393→    await this.authMethodRepository.save({
394→      userId,
395→      type: authMethodType,
396→      identifier: identifierHash,
397→      identifierHash,
398→      identifierDisplay: payload.email ? this.siweService.truncateEmail(payload.email) : identifier,
399→      lastUsedAt: new Date(),
400→    });
401→
402→    // 6. Return updated list of methods
403→    return this.getLinkedMethods(userId);
404→  }
