  1→import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { Repository, MoreThan } from 'typeorm';
  4→import { DeviceApproval } from './device-approval.entity';
  5→import { CreateApprovalDto } from './dto/create-approval.dto';
  6→import { RespondApprovalDto } from './dto/respond-approval.dto';
  7→
  8→/** Approval request TTL: 5 minutes */
  9→const TTL_MS = 5 * 60 * 1000;
 10→
 11→/** Maximum concurrent pending approval requests per user */
 12→const MAX_PENDING_REQUESTS = 5;
 13→
 14→@Injectable()
 15→export class DeviceApprovalService {
 16→  constructor(
 17→    @InjectRepository(DeviceApproval)
 18→    private readonly repo: Repository<DeviceApproval>
 19→  ) {}
 20→
 21→  /**
 22→   * Create a new approval request for a device.
 23→   * Sets expiresAt to 5 minutes from now.
 24→   */
 25→  async createRequest(userId: string, dto: CreateApprovalDto): Promise<{ requestId: string }> {
 26→    const pendingCount = await this.repo.count({
 27→      where: {
 28→        userId,
 29→        status: 'pending' as const,
 30→        expiresAt: MoreThan(new Date()),
 31→      },
 32→    });
 33→
 34→    if (pendingCount >= MAX_PENDING_REQUESTS) {
 35→      throw new BadRequestException(
 36→        `Maximum of ${MAX_PENDING_REQUESTS} pending approval requests allowed`
 37→      );
 38→    }
 39→
 40→    const approval = this.repo.create({
 41→      userId,
 42→      deviceId: dto.deviceId,
 43→      deviceName: dto.deviceName,
 44→      ephemeralPublicKey: dto.ephemeralPublicKey,
 45→      status: 'pending',
 46→      expiresAt: new Date(Date.now() + TTL_MS),
 47→    });
 48→
 49→    const saved = await this.repo.save(approval);
 50→    return { requestId: saved.id };
 51→  }
 52→
 53→  /**
 54→   * Get the status of an approval request.
 55→   * Auto-expires pending requests that have passed their TTL.
 56→   */
 57→  async getStatus(
 58→    requestId: string,
 59→    userId: string
 60→  ): Promise<{
 61→    status: string;
 62→    encryptedFactorKey?: string;
 63→  }> {
 64→    const approval = await this.repo.findOne({
 65→      where: { id: requestId, userId },
 66→    });
 67→
 68→    if (!approval) {
 69→      throw new NotFoundException('Approval request not found');
 70→    }
 71→
 72→    // Auto-expire pending requests past TTL
 73→    if (approval.status === 'pending' && approval.expiresAt < new Date()) {
 74→      approval.status = 'expired';
 75→      await this.repo.save(approval);
 76→    }
 77→
 78→    return {
 79→      status: approval.status,
 80→      ...(approval.encryptedFactorKey ? { encryptedFactorKey: approval.encryptedFactorKey } : {}),
 81→    };
 82→  }
 83→
 84→  /**
 85→   * Get all pending (non-expired) approval requests for a user.
 86→   */
 87→  async getPending(userId: string): Promise<
 88→    Array<{
 89→      requestId: string;
 90→      deviceId: string;
 91→      deviceName: string;
 92→      ephemeralPublicKey: string;
 93→      createdAt: Date;
 94→      expiresAt: Date;
 95→    }>
 96→  > {
 97→    const approvals = await this.repo.find({
 98→      where: {
 99→        userId,
100→        status: 'pending' as const,
101→        expiresAt: MoreThan(new Date()),
102→      },
103→      order: { createdAt: 'DESC' },
104→    });
105→
106→    return approvals.map((a) => ({
107→      requestId: a.id,
108→      deviceId: a.deviceId,
109→      deviceName: a.deviceName,
110→      ephemeralPublicKey: a.ephemeralPublicKey,
111→      createdAt: a.createdAt,
112→      expiresAt: a.expiresAt,
113→    }));
114→  }
115→
116→  /**
117→   * Respond to an approval request (approve or deny).
118→   * On approve, stores the ECIES-encrypted factor key.
119→   */
120→  async respond(requestId: string, userId: string, dto: RespondApprovalDto): Promise<void> {
121→    await this.repo.manager.transaction(async (manager) => {
122→      const approval = await manager.findOne(DeviceApproval, {
123→        where: { id: requestId, userId },
124→        lock: { mode: 'pessimistic_write' },
125→      });
126→
127→      if (!approval) {
128→        throw new NotFoundException('Approval request not found');
129→      }
130→
131→      if (approval.status !== 'pending') {
132→        throw new BadRequestException('Approval request has already been responded to');
133→      }
134→
135→      if (approval.expiresAt < new Date()) {
136→        approval.status = 'expired';
137→        await manager.save(approval);
138→        throw new BadRequestException('Approval request has expired');
139→      }
140→
141→      // H-02: Prevent self-approval — responding device must differ from requesting device
142→      if (dto.respondedByDeviceId === approval.deviceId) {
143→        throw new BadRequestException('A device cannot approve its own request');
144→      }
145→
146→      if (dto.action === 'approve') {
147→        // H-03: Require encryptedFactorKey when approving (defense-in-depth)
148→        if (!dto.encryptedFactorKey) {
149→          throw new BadRequestException('encryptedFactorKey is required when approving');
150→        }
151→        approval.encryptedFactorKey = dto.encryptedFactorKey;
152→      }
153→
154→      approval.status = dto.action === 'approve' ? 'approved' : 'denied';
155→      approval.respondedBy = dto.respondedByDeviceId;
156→      await manager.save(approval);
157→    });
158→  }
159→
160→  /**
161→   * Cancel a pending approval request.
162→   * Only works for pending requests owned by the calling user.
163→   */
164→  async cancel(requestId: string, userId: string): Promise<void> {
165→    const approval = await this.repo.findOne({
166→      where: { id: requestId, userId },
167→    });
168→
169→    if (!approval) {
170→      throw new NotFoundException('Approval request not found');
171→    }
172→
173→    if (approval.status !== 'pending') {
174→      throw new NotFoundException('Only pending requests can be cancelled');
175→    }
176→
177→    await this.repo.remove(approval);
178→  }
179→}
