223→  @Post('identity/wallet')
224→  @HttpCode(HttpStatus.OK)
225→  @UseGuards(ThrottlerGuard)
226→  @Throttle({ default: { limit: 5, ttl: 900000 } }) // 5 per 15min per IP
227→  @ApiOperation({
228→    summary: 'Verify SIWE wallet signature and return CipherBox identity JWT',
229→  })
230→  @ApiResponse({
231→    status: 200,
232→    description: 'Wallet verified, JWT issued',
233→    type: IdentityTokenResponseDto,
234→  })
235→  @ApiResponse({ status: 401, description: 'Invalid nonce or signature' })
236→  async walletLogin(@Body() dto: WalletVerifyDto): Promise<IdentityTokenResponseDto> {
237→    // 1. Parse the message to extract nonce
238→    const parsed = parseSiweMessage(dto.message);
239→    if (!parsed.nonce) {
240→      throw new UnauthorizedException('Invalid SIWE message: missing nonce');
241→    }
242→
243→    // 2. Consume nonce from Redis (single-use)
244→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
245→    let nonceDeleted: number;
246→    try {
247→      nonceDeleted = await this.redis.del(nonceKey);
248→    } catch (err) {
249→      this.logger.error('Redis error during nonce consumption', err);
250→      throw new UnauthorizedException('Nonce verification failed');
251→    }
252→    if (!nonceDeleted) {
253→      throw new UnauthorizedException('Invalid or expired nonce');
254→    }
255→
256→    // 3. Verify SIWE message + signature
257→    const walletAddress = await this.siweService.verifySiweMessage(
258→      dto.message,
259→      dto.signature as `0x${string}`,
260→      parsed.nonce
261→    );
262→
263→    // 5. Link intent: just verify ownership and issue JWT (no user creation)
264→    if (dto.intent === 'link') {
265→      const idToken = await this.jwtIssuerService.signIdentityJwt('link-verification');
266→      this.logger.log(`Wallet link verification: address=${walletAddress}`);
267→      return { idToken, userId: '', isNewUser: false };
268→    }
269→
270→    // 6. Find or create user by wallet address hash
271→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
272→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
273→    const { user, isNewUser } = await this.findOrCreateUserByIdentifier(
274→      addressHash,
275→      truncated,
276→      'wallet'
277→    );
278→
279→    // 7. Issue CipherBox JWT (sub=userId)
280→    const idToken = await this.jwtIssuerService.signIdentityJwt(user.id);
281→
282→    this.logger.log(`Wallet login: userId=${user.id}, isNew=${isNewUser}`);
283→
284→    return { idToken, userId: user.id, isNewUser };
285→  }
286→
287→  /**
288→   * Find an existing user by hashed identifier in the AuthMethod table, or create a new user.
289→   *
290→   * Each auth method type is independent -- no cross-method email matching.
291→   * Users link methods explicitly via Settings, not auto-linked by email.
292→   *
293→   * For identity provider flow, the publicKey is set to a placeholder because
294→   * the actual MPC-derived publicKey is not known until the client completes
295→   * Core Kit login with the CipherBox JWT.
296→   */
297→  private async findOrCreateUserByIdentifier(
298→    identifierHash: string,
299→    identifierDisplay: string,
300→    authMethodType: 'google' | 'email' | 'wallet'
301→  ): Promise<{ user: User; isNewUser: boolean }> {
302→    // Look for existing auth method with this hash
303→    const existingMethod = await this.authMethodRepository.findOne({
304→      where: {
305→        type: authMethodType,
306→        identifierHash,
307→      },
308→      relations: ['user'],
309→    });
310→
311→    if (existingMethod) {
312→      // Update last used timestamp
313→      existingMethod.lastUsedAt = new Date();
314→      await this.authMethodRepository.save(existingMethod);
315→      return { user: existingMethod.user, isNewUser: false };
316→    }
317→
318→    // No cross-method linking -- create new user with unique temporary publicKey
319→    const tempId = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
320→    const newUser = await this.userRepository.save({
321→      publicKey: `pending-core-kit-${tempId}`,
322→    });
323→    // Update placeholder with actual userId now that we have it
324→    newUser.publicKey = `pending-core-kit-${newUser.id}`;
325→    await this.userRepository.save(newUser);
326→
327→    // Create auth method with hash-based identifier
328→    await this.authMethodRepository.save({
329→      userId: newUser.id,
330→      type: authMethodType,
331→      identifier: identifierHash,
332→      identifierHash,
333→      identifierDisplay,
334→      lastUsedAt: new Date(),
335→    });
336→
337→    return { user: newUser, isNewUser: true };
338→  }
339→}
