 81→    await loginPage.selectWalletConnector('Mock Wallet');
 82→
 83→    // The mock wallet auto-approves connectAsync and signMessage.
 84→    // The SIWE flow will:
 85→    // 1. Connect wallet (auto-approved)
 86→    // 2. Fetch nonce from backend
 87→    // 3. Create SIWE message
 88→    // 4. Sign message (auto-approved)
 89→    // 5. Verify on backend
 90→    // 6. Continue with Core Kit login
 91→    //
 92→    // Wait for either:
