109→        const error = await loginPage.getWalletError();
110→        if (error) return 'error' as const;
111→        if (status) return 'in-progress' as const;
112→        return 'timeout' as const;
113→      }),
114→    ]);
115→
116→    if (result === 'redirected') {
117→      // Full SIWE flow completed - user is logged in
118→      await expect(page).toHaveURL(/.*files/);
119→    } else {
120→      // SIWE flow started but may have failed at backend/Core Kit step.
121→      // This is acceptable - the important thing is:
