127→
128→      // The flow should NOT show "No wallet detected" since we installed mock
129→      const error = await loginPage.getWalletError();
130→      if (error) {
131→        expect(error).not.toContain('No wallet detected');
132→        expect(error).not.toContain('no wallet');
